.sc-tw :root{
    --color-bg: oklch(98% 0.01 240);
    --color-moss: oklch(88% 0.1 150);
    --color-text: oklch(15% 0.02 240);
    --font-hero: 'Cormorant Garamond', serif;
    --font-tech: 'DM Sans', sans-serif;
