    background-color: var(--color-bg);
    color: var(--color-text);
    font-family: var(--font-tech);
    overflow-x: hidden;
    line-height: 1.6;
    border-radius: 0;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
  }.sc-tw ::selection{
    background: var(--color-moss);
    color: white;
  }.sc-tw h1,.sc-tw h2,.sc-tw h3{
    font-family: var(--font-hero);
    font-weight: 500;
    letter-spacing: -0.02em;
  }.sc-tw .fullscreen-video-container{
    position: absolute;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 0;
    overflow: hidden;
    border-radius: 0;
  }.sc-tw .fullscreen-video-container video{
    width: 100%;
    height: 100%;
    object-fit: cover;
    filter: saturate(1.2) contrast(1.1) brightness(0.85);
    border-radius: 0;
  }.sc-tw .video-vignette{
    position: absolute;
    inset: 0;
    background: radial-gradient(circle at center, transparent 0%, rgba(0,0,0,0.4) 60%, var(--color-bg) 100%);
    border-radius: 0;
    z-index: 1;
    pointer-events: none;
  }.sc-tw .hero-typography{
    position: relative;
    z-index: 20;
    padding: 3rem;
    transform: translate3d(0, 0, 0);
    will-change: transform, opacity;
  }.sc-tw .dew-drop{
    display: inline-flex;
    align-items: center;
    gap: 12px;
    padding: 16px 36px;
    background: linear-gradient(135deg, rgba(255,255,255,0.15) 0%, rgba(255,255,255,0.05) 100%);
    backdrop-filter: blur(24px) saturate(1.8);
    -webkit-backdrop-filter: blur(24px) saturate(1.8);
    border: 0.5px solid rgba(255,255,255,0.4);
    box-shadow: 
      inset 0 1px 2px rgba(255,255,255,0.5),
      inset 0 -1px 4px rgba(255,255,255,0.1),
      0 12px 32px rgba(0,0,0,0.2);
    border-radius: 100px;
    color: white;
    text-decoration: none;
    font-weight: 500;
    font-size: 0.9rem;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    transition: all 0.5s cubic-bezier(0.25, 1, 0.5, 1);
    cursor: pointer;
    position: relative;
    overflow: hidden;
  }.sc-tw .dew-drop::before{
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    border-radius: 100px;
    box-shadow: inset 0 0 20px rgba(255,255,255,0.4);
    opacity: 0;
    transition: opacity 0.5s ease;
  }.sc-tw .dew-drop:hover{
    transform: translateY(-4px) scale(1.02);
    box-shadow: 
      inset 0 1px 2px rgba(255,255,255,0.8),
      inset 0 -1px 4px rgba(255,255,255,0.2),
      0 20px 48px rgba(0,0,0,0.4);
    background: linear-gradient(135deg, rgba(255,255,255,0.25) 0%, rgba(255,255,255,0.1) 100%);
  }.sc-tw .dew-drop:hover::before{
    opacity: 1;
  }.sc-tw .rhizome-section{
    position: relative;
    padding: 12vh 5vw;
    container-type: inline-size;
    container-name: rhizome;
    background: var(--color-bg);
    border-radius: 0;
    z-index: 10;
  }.sc-tw .radial-leak{
    position: absolute;
    width: 60vw;
    height: 60vw;
    background: radial-gradient(circle, oklch(88% 0.1 150 / 0.15) 0%, transparent 60%);
    border-radius: 50%;
    filter: blur(50px);
    z-index: 0;
    pointer-events: none;
  }.sc-tw .bionic-bloom{
    animation: bloom-scroll linear both;
    animation-timeline: view();
    animation-range: entry 5% cover 35%;
  }

