      opacity: 0;
      transform: translateY(40px) scale(0.98);
      filter: blur(8px);
    }to{
      opacity: 1;
      transform: translateY(0) scale(1);
      filter: none;
    }
  }.sc-tw .hero-fade-in{
    animation: fadeIn 1.5s cubic-bezier(0.25, 1, 0.5, 1) forwards;
